/* ---------- Helpers ---------- */
const SIM_NOW = new Date("2026-03-31T12:00:00");
const ROLES = ["Administrator","Director","Specialist","Lead","Attendant"];
const nid = () => Math.random().toString(36).slice(2,8).toUpperCase();
const locDisplay = (l) => l ? (l.subName || l.name) : "Unknown";
const fmtDate = d => {
  // Used in Admin Audit Log + Hardware "Last Seen". Module-scope helper because
  // it's a presentational concern, not data. NOTE(merge): consolidate with any
  // other date helpers introduced in later module ports.
  const dt = typeof d === "string" ? new Date(d) : d;
  return isNaN(dt?.getTime()) ? d : dt.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"});
};

// ── Added in Phase B.2 for Dashboard port ──
// fmt24to12: "06:00" → "6:00 AM". Used by Dashboard for shift time display.
const fmt24to12 = t => {
  if (!t) return "—";
  const [h,m] = t.split(":");
  const hr = +h;
  return `${hr===0?12:hr>12?hr-12:hr}:${m} ${hr>=12?"PM":"AM"}`;
};
// daysBetween: integer days from a to b. Negative = a is later than b.
// Used by Dashboard for "Nd overdue" / "Nd left" deadline calculations.
const daysBetween = (a,b) => Math.ceil((new Date(b)-new Date(a))/(1000*60*60*24));

// ── Added in Phase B.3 for Sales port ──
// now: short stamp "MM/DD HH:MM" for Sales note/hist/email entries. Uses real
// Date (not SIM_NOW) because Sales records when actions are *taken*, not when
// the demo data is *for*. NOTE(merge): production may want UTC + server time.
const now = () => {
  const d = new Date();
  return `${String(d.getMonth()+1).padStart(2,"0")}/${String(d.getDate()).padStart(2,"0")} ${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}`;
};
// B.7: parseDt("MM/DD HH:MM") → Date instance anchored at SIM_NOW's year.
// Used by CS (slaInfo, timeToClose, needsFollowUp predicates) and Dashboard
// (tickets SLA-breach check, adapted from new Date() since tickets format
// changed from ISO 8601 to MM/DD HH:MM in this port).
// Returns null for malformed inputs.
const parseDt = (s) => {
  if (!s) return null;
  const p = s.match(/(\d+)\/(\d+)\s+(\d+):(\d+)/);
  if (!p) return null;
  return new Date(SIM_NOW.getFullYear(), parseInt(p[1]) - 1, parseInt(p[2]), parseInt(p[3]), parseInt(p[4]));
};
// custName: "First Last" or "Unknown" fallback. Sales-defined; promoted to
// module scope so other modules (CS ticket details, Inventory taggedUser
// follow-ups) can reuse without redefinition.
const custName = (c) => c ? `${c.first} ${c.last}` : "Unknown";
// fmtDue: "Mar 31, 6:00 PM" — used by Sales kanban and Order Detail.
const fmtDue = (d) => {
  if (!d) return "N/A";
  const dt = new Date(d);
  return dt.toLocaleDateString("en-US",{month:"short",day:"numeric"}) + ", " + dt.toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit"});
};
// isDueSoon / isPastDue: kanban-card urgency colors. B.3: replaced Sales'
// three hardcoded `new Date("2026-03-31T12:00:00")` string literals with
// foundation's SIM_NOW Date object (same demo moment).
const isDueSoon = (due) => {
  if (!due) return false;
  const h = (new Date(due) - SIM_NOW) / (1000*60*60);
  return h <= 2 && h > 0;
};
const isPastDue = (due) => {
  if (!due) return false;
  return new Date(due) < SIM_NOW;
};
// needsReview: customer "info verification due" flag — 180 days since
// lastVerified (or createdAt fallback). Sales POS shows a §2.5 yellow
// callout when this returns true on the selected customer.
const needsReview = (cust) => {
  if (!cust) return false;
  const checkDate = cust.lastVerified || cust.createdAt;
  if (!checkDate) return true;
  const ms = SIM_NOW - new Date(checkDate);
  return ms > (180*24*60*60*1000);
};
// calcDueDate: returns ISO string for `startISO + hours`, skipping
// Sat/Sun if excludeWeekends. Used by Sales when an order is created
// to set the initial `due` from the product's turnaround config.
const calcDueDate = (startISO, hours, excludeWeekends) => {
  const start = new Date(startISO || Date.now());
  if (!hours) return new Date(start.getTime() + 48*60*60*1000).toISOString();
  if (!excludeWeekends) return new Date(start.getTime() + hours*60*60*1000).toISOString();
  let remaining = hours;
  const d = new Date(start);
  while (remaining > 0) {
    d.setHours(d.getHours()+1);
    const day = d.getDay();
    if (day !== 0 && day !== 6) remaining--;
  }
  return d.toISOString();
};
// recalcDueAfterHold: when an order is released from On Hold, shifts the
// due-by date forward by the elapsed hold time so the customer's window
// isn't compressed.
const recalcDueAfterHold = (order) => {
  if (!order.holdAt || !order.due) return order.due;
  const holdStart = new Date(order.holdAt);
  const nowDate = new Date();
  const heldMs = nowDate - holdStart + (order.holdElapsed || 0) * 60*60*1000;
  return new Date(new Date(order.due).getTime() + heldMs).toISOString();
};
// triggerEmail: returns an email-log entry for the order.emails[] array.
// Standalone Sales does not actually send mail — this models the audit
// log of customer-facing email triggers.
const triggerEmail = (type, order, customer) => {
  const msgs = {
    created: `Order confirmation sent to ${customer?.email || "customer"}`,
    ready:   `"Order ready for pickup" sent to ${customer?.email || "customer"}`,
    reminder:`Pickup reminder sent to ${customer?.email || "customer"}`,
    final:   `"Final pickup notice — 15 days before donation" sent to ${customer?.email || "customer"}`,
  };
  return { type, at: now(), msg: msgs[type] || type };
};

const isAdmin = (u) => u?.role === "Administrator";
const isAD = (u) => ["Administrator","Director"].includes(u?.role);
const isSpecPlus = (u) => ["Administrator","Director","Specialist"].includes(u?.role);

// B.8 — Depth-1 reports for the user `uid` from the foundation's existing
// `supervisorId` graph (set on every seed user, owned by HR/Admin user-edit
// form). Returns an array of subordinate user ids.
//
// T&A reads this to scope its pending-time-off and timesheets-review filters
// to "people I directly supervise" (Maria sees Nina's requests; Tyler sees
// Aisha's). T&A standalone used a denormalized `user.supervisorOf` array for
// this; the merged foundation derives it on the fly to keep `supervisorId`
// the single source of truth for the supervisory graph.
//
// NOTE(merge): HR (B.12) lands a recursive variant `getSubs(uid, users)` that
// walks the full descendant tree (Director → Lead → Attendant, depth-N). Both
// helpers read the same `supervisorId` graph; HR's recursion adds depth, this
// one stays at depth-1 because T&A's semantics are "direct reports only" —
// a Lead does not see their Lead-peer's reports' requests. Ledger #22.
const directReports = (uid, users) => users.filter(u => u.hasSupervisor && u.supervisorId === uid).map(u => u.id);

