// ---- 6-box code input ----
const CodeBox = ({ digit, refCb, onChange, onKeyDown, onPaste }) => {
  const [foc, setFoc] = useState(false);
  const filled = digit && digit !== " ";
  return (
    <input
      ref={refCb}
      type="text"
      inputMode="numeric"
      maxLength={1}
      value={filled ? digit : ""}
      onChange={onChange}
      onKeyDown={onKeyDown}
      onPaste={onPaste}
      onFocus={(e) => { setFoc(true); e.target.select(); }}
      onBlur={() => setFoc(false)}
      style={{
        width:52, height:60,
        fontSize:22, fontWeight:600,
        fontFamily:"DM Sans, sans-serif",
        textAlign:"center",
        border:`1.5px solid ${foc || filled ? C.red : "#D1D5DB"}`,
        borderRadius:10, outline:"none",
        background:C.wh, color:C.blk,
        boxShadow: foc ? `0 0 0 3px ${C.redLt}80` : "none",
        transition:"border-color 0.15s ease, box-shadow 0.15s ease",
        boxSizing:"border-box",
      }}
    />
  );
};

const CodeInput = ({ value, onChange, autoFocus }) => {
  const refs = useRef([]);
  const digits = value.padEnd(6, " ").split("").slice(0, 6);

  useEffect(() => {
    if (autoFocus && refs.current[0]) refs.current[0].focus();
  }, [autoFocus]);

  const handleChange = (idx) => (e) => {
    const v = e.target.value.replace(/\D/g, "").slice(0, 1);
    const cur = value.padEnd(6, " ").split("");
    cur[idx] = v || " ";
    const next = cur.join("").replace(/ /g, "");
    onChange(next);
    if (v && idx < 5 && refs.current[idx + 1]) {
      refs.current[idx + 1].focus();
    }
  };

  const handleKeyDown = (idx) => (e) => {
    if (e.key === "Backspace" && !digits[idx].trim() && idx > 0) {
      refs.current[idx - 1]?.focus();
    }
    if (e.key === "ArrowLeft" && idx > 0) refs.current[idx - 1]?.focus();
    if (e.key === "ArrowRight" && idx < 5) refs.current[idx + 1]?.focus();
  };

  const handlePaste = (e) => {
    e.preventDefault();
    const pasted = e.clipboardData.getData("text").replace(/\D/g, "").slice(0, 6);
    if (pasted) {
      onChange(pasted);
      const lastIdx = Math.min(pasted.length, 6) - 1;
      if (lastIdx >= 0 && refs.current[lastIdx]) refs.current[lastIdx].focus();
    }
  };

  return (
    <div style={{ display:"flex", gap:10, justifyContent:"space-between" }}>
      {digits.map((d, idx) => (
        <CodeBox
          key={idx}
          digit={d}
          refCb={(el) => { refs.current[idx] = el; }}
          onChange={handleChange(idx)}
          onKeyDown={handleKeyDown(idx)}
          onPaste={handlePaste}
        />
      ))}
    </div>
  );
};

